const environment = relayEnvironmentWithMissingFieldHandlerForNode()

interface CopilotImmersiveEmbeddedProps extends CopilotImmersivePayload, ReactPartialAnchorProps {}

export function CopilotImmersiveEmbedded(props: CopilotImmersiveEmbeddedProps) {
  const inputRef = useRef<HTMLTextAreaElement>(null)
  return (
    <RelayEnvironmentProvider environment={environment}>
      <AppPayloadContext.Provider value={props}>
        <CopilotImmersiveProviders payload={props}>
          <CopilotHeaderButton inputRef={inputRef} reactPartialAnchor={props.reactPartialAnchor} />
        </CopilotImmersiveProviders>
      </AppPayloadContext.Provider>
    </RelayEnvironmentProvider>
  )
}

