function ExternalAnchorListener({reactPartialAnchor}: ReactPartialAnchorProps) {
  const manager = useChatManager()
  const onClick = useCallback(
    (e: MouseEvent) => {
      sendEvent('dotcom_chat.activate', {
        target: `GLOBAL_COPILOT_MENU_HEADER_TO_IMMERSIVE`,
        mode: 'global_nav',
      })
      e.preventDefault()
      void manager.openChat(null, 'thread', 'hacks', undefined, undefined, true)
    },
    [manager],
  )

  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  useOnAnchorClick(reactPartialAnchor!, onClick)
  return <></>
}

function EmbeddedImmersive({inputRef}: {inputRef: React.RefObject<HTMLTextAreaElement | null>}) {
  const {chatIsOpen} = useChatStateValues('chatIsOpen')
  const isContentPreviewOpen = useContentPreviewOpen()
  const {closePreviewPane} = useContentPreview()
  const manager = useChatManager()
  const {panelWidth, panelHeight, startResize, onResizerKeyDown} = useResizablePanel()
  const staffDialogRef = useRef<HTMLDivElement>(null)
  const [showStaffDialog, setShowStaffDialog] = useState<DialogType>(DialogType.None)

  const handleCloseChat = useCallback(() => {
    manager.closeChat()
  }, [manager])

  const handleCloseContentPreview = useCallback(() => {
    closePreviewPane()
  }, [closePreviewPane])
  return (
    chatIsOpen && (
      <>
        <ChatPanel
          handleClose={handleCloseChat}
          panelWidth={panelWidth}
          panelHeight={panelHeight}
          startResize={startResize}
          onResizerKeyDown={onResizerKeyDown}
          initialFocusRef={inputRef}
          staffDialogRef={staffDialogRef}
        >
          <Header
            staffDialogRef={staffDialogRef}
            showStaffDialog={showStaffDialog}
            setShowStaffDialog={setShowStaffDialog}
          />
          <ConversationView attachmentMenuSide="outside-top" isMobile textAreaRef={inputRef} />
        </ChatPanel>
        {isContentPreviewOpen && (
          <Dialog
            className={styles.contentPreviewDialog}
            onClose={handleCloseContentPreview}
            position={{narrow: 'fullscreen', regular: 'fullscreen', wide: 'fullscreen'}}
            title="Content Preview"
            renderHeader={() => null}
            renderBody={() => <EmbeddedContentPreview inputRef={inputRef} />}
          />
        )}
      </>
    )
  )
}

